create or replace function public.depurnrfi_d_create_run(p_run_id text,p_slate_date date,p_input_manifest jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v_count integer; begin if coalesce(trim(p_run_id),'')='' then raise exception 'DEPURNRFI_D_RUN_ID_REQUIRED'; end if; if p_slate_date is null then raise exception 'DEPURNRFI_D_SLATE_DATE_REQUIRED'; end if; if p_input_manifest is null or jsonb_typeof(p_input_manifest)<>'object' then raise exception 'DEPURNRFI_D_INPUT_MANIFEST_REQUIRED'; end if; perform set_config('depurnrfi_d.kernel_commit','on',true); insert into public.depurnrfi_d_runs(run_id,slate_date,input_manifest,source_sha256,status,phase_cursor) values(p_run_id,p_slate_date,p_input_manifest,'121f80c4569de1f87c438f96fbd48364a1756afee17a38f3f1f33698a67caea9','RUN_ACTIVE','F1'); insert into public.depurnrfi_d_requirement_state(run_id,requirement_id,phase_code,state) select p_run_id,requirement_id,phase_code,'NOT_EXECUTED' from public.depurnrfi_d_requirement_catalog where binding; select count(*) into v_count from public.depurnrfi_d_requirement_state where run_id=p_run_id; perform public.depurnrfi_d_append_event(p_run_id,'F1','RUN_CREATED',1,jsonb_build_object('slate_date',p_slate_date,'requirements_loaded',v_count,'source_sha256','121f80c4569de1f87c438f96fbd48364a1756afee17a38f3f1f33698a67caea9')); perform set_config('depurnrfi_d.kernel_commit','off',true); return jsonb_build_object('run_id',p_run_id,'status','RUN_ACTIVE','phase_cursor','F1','requirements_loaded',v_count,'auto_continue',true); end $$;

create or replace function public.depurnrfi_d_submit_phase(p_run_id text,p_phase_code text,p_output jsonb,p_requirements_evaluated jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare r public.depurnrfi_d_runs%rowtype; expected integer; got integer; arrlen integer; ord integer; next_phase text; out_hash text; new_ver integer; begin select * into r from public.depurnrfi_d_runs where run_id=p_run_id for update; if not found then raise exception 'DEPURNRFI_D_RUN_NOT_FOUND'; end if; if r.status<>'RUN_ACTIVE' then raise exception 'DEPURNRFI_D_RUN_NOT_ACTIVE status=%',r.status; end if; if r.phase_cursor<>p_phase_code then raise exception 'DEPURNRFI_D_ILLEGAL_PHASE_TRANSITION expected=% got=%',r.phase_cursor,p_phase_code; end if; if p_phase_code='REPORT_D' then raise exception 'DEPURNRFI_D_REPORT_MUST_USE_REPORT_COMMIT'; end if; select order_index,expected_requirement_count into ord,expected from public.depurnrfi_d_phase_catalog where phase_code=p_phase_code; if ord is null then raise exception 'DEPURNRFI_D_PHASE_UNKNOWN'; end if; if p_requirements_evaluated is null or jsonb_typeof(p_requirements_evaluated)<>'array' then raise exception 'DEPURNRFI_D_REQUIREMENT_MANIFEST_ARRAY_REQUIRED'; end if; arrlen=jsonb_array_length(p_requirements_evaluated); select count(distinct x.req_id) into got from jsonb_array_elements_text(p_requirements_evaluated) as x(req_id) join public.depurnrfi_d_requirement_catalog c on c.requirement_id=x.req_id where c.phase_code=p_phase_code and c.binding; if arrlen<>expected or got<>expected then raise exception 'DEPURNRFI_D_REQUIREMENT_COVERAGE_FAIL phase=% expected=% array=% valid_distinct=%',p_phase_code,expected,arrlen,got; end if; perform public.depurnrfi_d_validate_phase_output(p_phase_code,p_output); out_hash=public.depurnrfi_d_jsonb_hash(p_output); select phase_code into next_phase from public.depurnrfi_d_phase_catalog where order_index=ord+1; perform set_config('depurnrfi_d.kernel_commit','on',true); update public.depurnrfi_d_requirement_state s set state='SATISFIED',evaluated_at=clock_timestamp() where s.run_id=p_run_id and s.phase_code=p_phase_code and s.requirement_id in (select value from jsonb_array_elements_text(p_requirements_evaluated)); insert into public.depurnrfi_d_phase_receipts(run_id,phase_code,order_index,status,requirements_evaluated,output,output_hash) values(p_run_id,p_phase_code,ord,'COMMITTED',expected,p_output,out_hash); new_ver=r.state_version+1; update public.depurnrfi_d_runs set phase_cursor=next_phase,state_version=new_ver,updated_at=clock_timestamp() where run_id=p_run_id; perform public.depurnrfi_d_append_event(p_run_id,p_phase_code,'PHASE_COMMITTED',new_ver,jsonb_build_object('output_hash',out_hash,'requirements_evaluated',expected,'next_phase',next_phase)); perform set_config('depurnrfi_d.kernel_commit','off',true); return jsonb_build_object('run_id',p_run_id,'phase',p_phase_code,'status','COMMITTED','output_hash',out_hash,'next_phase',next_phase,'auto_continue',true); end $$;

create or replace function public.depurnrfi_d_commit_pre_dialogue_report(p_run_id text,p_artifact_id text,p_report_sections jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare r public.depurnrfi_d_runs%rowtype; c integer; payload text; h text; rid uuid; f11 text; new_ver integer; begin select * into r from public.depurnrfi_d_runs where run_id=p_run_id for update; if not found then raise exception 'DEPURNRFI_D_RUN_NOT_FOUND'; end if; if r.status<>'RUN_ACTIVE' or r.phase_cursor<>'REPORT_D' then raise exception 'DEPURNRFI_D_REPORT_NOT_READY status=% phase=%',r.status,r.phase_cursor; end if; select output_hash into f11 from public.depurnrfi_d_phase_receipts where run_id=p_run_id and phase_code='F11'; if f11 is null then raise exception 'DEPURNRFI_D_F11_RECEIPT_REQUIRED'; end if; if p_report_sections is null or jsonb_typeof(p_report_sections)<>'object' then raise exception 'DEPURNRFI_D_REPORT_OBJECT_REQUIRED'; end if; if coalesce(p_report_sections->>'report_type','')<>'FINAL_DEPURATION_REPORT_D' then raise exception 'DEPURNRFI_D_REPORT_TYPE_INVALID'; end if; begin c=(p_report_sections->>'candidate_count')::integer; exception when others then raise exception 'DEPURNRFI_D_REPORT_CANDIDATE_COUNT_REQUIRED'; end; if c<0 or c>4 then raise exception 'DEPURNRFI_D_REPORT_MAX_FOUR_VIOLATION'; end if; if jsonb_typeof(p_report_sections->'candidate_dossiers')<>'array' or jsonb_array_length(p_report_sections->'candidate_dossiers')<>c then raise exception 'DEPURNRFI_D_REPORT_CANDIDATE_DOSSIERS_MISMATCH'; end if; if not (p_report_sections ? 'exclusion_ledger' and p_report_sections ? 'd1_findings_summary' and p_report_sections ? 'd2_reconstruction_delta' and p_report_sections ? 'facts' and p_report_sections ? 'analyst_interpretation' and p_report_sections ? 'unresolved' and p_report_sections ? 'dialogue_topics' and p_report_sections ? 'chat_payload') then raise exception 'DEPURNRFI_D_REPORT_REQUIRED_SECTION_MISSING'; end if; payload=coalesce(p_report_sections->>'chat_payload',''); if length(trim(payload))<50 then raise exception 'DEPURNRFI_D_COMPLETE_CHAT_REPORT_REQUIRED'; end if; if public.depurnrfi_d_has_forbidden_key(p_report_sections,array['final_nrfi','final_nrfi_bet','bet','bet_size','probability','fair_price','edge','lock','rank_1_to_4']) then raise exception 'DEPURNRFI_D_REPORT_BETTING_AUTHORITY_FORBIDDEN'; end if; h=public.depurnrfi_d_jsonb_hash(p_report_sections); perform set_config('depurnrfi_d.kernel_commit','on',true); insert into public.depurnrfi_d_pre_dialogue_reports(run_id,artifact_id,report_type,candidate_count,report_sections,chat_payload,report_hash) values(p_run_id,p_artifact_id,'FINAL_DEPURATION_REPORT_D',c,p_report_sections,payload,h) returning report_id into rid; insert into public.depurnrfi_d_phase_receipts(run_id,phase_code,order_index,status,requirements_evaluated,output,output_hash) values(p_run_id,'REPORT_D',14,'COMMITTED',0,p_report_sections,h); new_ver=r.state_version+1; update public.depurnrfi_d_runs set status='WAITING_USER_AUTHORIZATION',phase_cursor='DIALOGUE',state_version=new_ver,pre_dialogue_frozen=true,report_id=rid,updated_at=clock_timestamp() where run_id=p_run_id; perform public.depurnrfi_d_append_event(p_run_id,'REPORT_D','PRE_DIALOGUE_REPORT_FROZEN',new_ver,jsonb_build_object('report_id',rid,'report_hash',h,'candidate_count',c,'next_state','STOP_WAITING_USER_AUTHORIZATION')); perform set_config('depurnrfi_d.kernel_commit','off',true); return jsonb_build_object('report_id',rid,'report_hash',h,'candidate_count',c,'chat_payload',payload,'next_state','STOP_WAITING_USER_AUTHORIZATION','auto_continue',false); end $$;

create or replace function public.depurnrfi_d_get_state(p_run_id text) returns jsonb language sql security definer set search_path=public,extensions as $$ select jsonb_build_object('run',to_jsonb(r),'phases',(select coalesce(jsonb_agg(to_jsonb(x) order by x.order_index),'[]'::jsonb) from public.depurnrfi_d_phase_receipts x where x.run_id=r.run_id),'report',(select to_jsonb(pr) from public.depurnrfi_d_pre_dialogue_reports pr where pr.run_id=r.run_id),'dialogue_turns',(select coalesce(jsonb_agg(to_jsonb(t) order by t.turn_number),'[]'::jsonb) from public.depurnrfi_d_dialogue_turns t where t.run_id=r.run_id),'closing',(select to_jsonb(c) from public.depurnrfi_d_dialogue_closings c where c.run_id=r.run_id),'manual_gate',jsonb_build_object('required',true,'user_mediated',true,'auto_chain_forbidden',true,'one_authorization_per_d_response',true,'complete_chat_payload_required',true,'d_closes_first',true,'a_closes_system',true)) from public.depurnrfi_d_runs r where r.run_id=p_run_id $$;

revoke all on function public.depurnrfi_d_create_run(text,date,jsonb) from public,anon,authenticated; revoke all on function public.depurnrfi_d_submit_phase(text,text,jsonb,jsonb) from public,anon,authenticated; revoke all on function public.depurnrfi_d_commit_pre_dialogue_report(text,text,jsonb) from public,anon,authenticated; revoke all on function public.depurnrfi_d_get_state(text) from public,anon,authenticated;
grant execute on function public.depurnrfi_d_create_run(text,date,jsonb) to service_role; grant execute on function public.depurnrfi_d_submit_phase(text,text,jsonb,jsonb) to service_role; grant execute on function public.depurnrfi_d_commit_pre_dialogue_report(text,text,jsonb) to service_role; grant execute on function public.depurnrfi_d_get_state(text) to service_role;
